SELECT * FROM renew_application
WHERE status = #{status}
ORDER BY apply_date DESC

SELECT * FROM renew_application
WHERE borrow_id = #{borrowId} AND status = #{status}
LIMIT 1

SELECT * FROM renew_application
WHERE borrow_id = #{borrowId}
ORDER BY CASE WHEN audit_date IS NULL THEN 1 ELSE 0 END, audit_date DESC

SELECT * FROM renew_application WHERE borrow_id IN
#{id}
ORDER BY CASE WHEN status = 0 THEN 1 ELSE 0 END, audit_date DESC

SELECT ra.*, t.name as teacher_name, b.title as book_title FROM renew_application ra LEFT JOIN teacher t ON ra.teacher_id = t.id LEFT JOIN borrow_record br ON ra.borrow_id = br.id LEFT JOIN book b ON br.book_id = b.id
AND t.name LIKE CONCAT('%', #{teacherName}, '%')
AND b.title LIKE CONCAT('%', #{bookTitle}, '%')
AND ra.status = #{status}
ORDER BY ra.apply_date DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE renew_application
SET status = #{status}, audit_date = NOW(),
    audit_admin_id = #{auditAdminId}, audit_remark = #{auditRemark}
WHERE id = #{id}
